package com.fakrudeenmart.servlet;
import com.fakrudeenmart.service.AdminService;
import javax.servlet.ServletException; import javax.servlet.http.*; import java.io.IOException;
public class AdminProductListServlet extends HttpServlet { private AdminService service; public void init(){service=new AdminService();} protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{Long category=null,seller=null;try{if(req.getParameter("categoryId")!=null&&!req.getParameter("categoryId").isBlank())category=AdminServletSupport.id(req.getParameter("categoryId"),"Category was not found.");if(req.getParameter("sellerId")!=null&&!req.getParameter("sellerId").isBlank())seller=AdminServletSupport.id(req.getParameter("sellerId"),"Seller was not found.");}catch(AdminService.AdminException e){req.setAttribute("error",e.getMessage());}req.setAttribute("products",service.getProducts(AdminServletSupport.adminId(req),req.getParameter("search"),category,seller,AdminServletSupport.productStatus(req.getParameter("status")),req.getParameter("stock")==null?null:"IN".equals(req.getParameter("stock"))));req.setAttribute("categories",new com.fakrudeenmart.service.CategoryService().getAllCategories());req.setAttribute("sellers",service.getSellers(AdminServletSupport.adminId(req),null,null));req.getRequestDispatcher("/WEB-INF/views/admin/products.jsp").forward(req,resp);} }
